#define MOD 1000000007

int is_prime(int n) {
    if (n < 2) return 0;
    if (n == 2) return 1;
    if (n % 2 == 0) return 0;
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int main() {
    int N;
    scanf("%d", &N);

    long long result = 1;

    for (int p = 2; p <= N; p++) {
        if (!is_prime(p)) continue;
        int count = 0;
        int power = p;
        while (power <= N) {
            count += N / power;
            if (power > N / p) break; // avoid overflow
            power *= p;
        }
        result = (result * (count + 1)) % MOD;
    }

    printf("%lld\n", result);
    return 0;
}

