                primes.add(i);
                for (long j = (long)i * i; j <= n; j += i) {
                    isComposite[(int)j] = true;
                }
            }
        }

        long result = 1;
        for (int p : primes) {
            // Compute exponent of p in N!
            long exp = 0;
            long pk = p;
            while (pk <= N) {
                exp += N / pk;
                if (pk > N / p) break; // prevent overflow
                pk *= p;
            }
            result = result * ((exp + 1) % MOD) % MOD;
        }

        System.out.println(result);
    }
